//! Compare 91FBA0 scripted descriptor dispatch to retained native rows.
use spore_core::cell_provider_descriptor_dispatch_v1::{project,Action};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let p=std::env::args().nth(1).expect("native stdout");let b=std::fs::read(p).unwrap();assert_eq!(b.len(),192);for i in 0..8{let k=i%4;let cw=if i>=4{0x37f}else{0x27f};let explicit=if k==3{Some(1)}else{None};let lookup=if k==0{Some(None)}else if k==3{None}else{Some(Some(1))};let result=match k{0=>None,1=>Some(None),_=>Some(Some(2))};let x=project(0x12345678,0,explicit,lookup,result,cw,0x1f80,true).unwrap();let row=&b[i*24..(i+1)*24];assert_eq!(w(row,0),u32::from(x.result.is_some()));assert_eq!(w(row,4),u32::from(x.actions.contains(&Action::Lookup{key:0x12345678})));assert_eq!(w(row,8),u32::from(k!=0));assert_eq!(w(row,12),0);let fp=w(row,16);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,20)&!0x3f,0x1f80);}println!("matched 8 retained descriptor dispatch rows; callbacks scripted");}
